contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // param newOwner: address to try setting; param callerIsOwner: if true, the test contract will act as the owner by using the initial owner (the deployer of c was this test contract)
    function run(address newOwner, bool callAsOwner) public payable {
        require(newOwner != address(0));
        // At deployment of c, constructor set owner = msg.sender, and the checker deploys a fresh c with msg.sender == this InvMutTest contract.
        // So initially c.owner() == address(this).
        address beforeOwner = c.owner();

        bool reverted;
        // Make the call from this contract (all calls originate from this test contract). To simulate attempted non-owner call, we rely on the fact
        // only the owner (this contract) can call setOwner successfully. If callAsOwner == true, we call setOwner expecting success;
        // if false, we attempt to emulate a non-owner by first transferring ownership away so that this contract is no longer owner,
        // then attempt to call setOwner which should revert.

        if (callAsOwner) {
            // this contract is the owner initially, so call should succeed and owner becomes newOwner
            bool ok = c.setOwner(newOwner);
            reverted = false;
            // ok should be true per function signature, but we capture via return value
        } else {
            // Transfer ownership away first (this will succeed because this contract is owner)
            bool ok1 = c.setOwner(address(0x1234567890123456789012345678901234567890));
            // Now this contract is no longer the owner. A subsequent call to setOwner must revert.
            try c.setOwner(newOwner) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        address afterOwner = c.owner();

        // General rule:
        // - If the call was attempted while this contract was the owner (callAsOwner==true), the call must succeed and owner becomes newOwner.
        // - If the call was attempted when this contract was not the owner (callAsOwner==false), the attempted setOwner must revert and owner remains as set by the intermediate transfer.
        if (callAsOwner) {
            assert(afterOwner == newOwner);
        } else {
            // afterOwner must equal the intermediate address we set (0x123..90) and the last attempt must have reverted
            assert(reverted && afterOwner == address(0x1234567890123456789012345678901234567890));
        }
    }

    receive() external payable {}
}

