        // At deployment of c, owner == msg.sender == this contract.
        address beforeOwner = c.owner();

        bool firstCallSucceeded;
        bool secondCallReverted;

        // We will perform up to two top-level state-changing calls on c as required by the scenario.
        if (callAsOwner) {
