contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // newOwner: address to attempt to set; callerIsOwner: if true we rely on being the owner (initially true),
    // otherwise we first transfer ownership away so the subsequent attempt should revert.
    function run(address newOwner, bool callerIsOwner) public payable {
        require(newOwner != address(0));

        // Read owner before any actions
        address ownerBefore = c.owner();

        bool callReverted;
        bool callReturnedBool;

        if (callerIsOwner) {
            // As deployed, this contract is the owner of c, so perform the single state-changing call.
            // This must be a top-level state-changing call.
            callReturnedBool = c.setOwner(newOwner);
            callReverted = false;
        } else {
            // First transfer ownership away so this contract is NOT the owner anymore.
            // Use a top-level call to change state.
            address other = address(0x123);
            bool first = c.setOwner(other);
            // Now attempt the call that should revert because msg.sender != owner
            try c.setOwner(newOwner) {
                callReverted = false;
                callReturnedBool = true;
            } catch {
                callReverted = true;
                callReturnedBool = false;
            }
            // ownerBefore should reflect the owner at start; after first transfer owner changed to other
            // but that is observed below via c.owner().
            // Silence unused variable warning for first
            if (!first) { revert(); }
        }

        address ownerAfter = c.owner();

        // General rule:
        // - If callerIsOwner: the call did not revert, returned true, and owner equals newOwner.
        // - If not callerIsOwner: the attempted call reverted and owner did not become newOwner.
        assert(
            (callerIsOwner && !callReverted && callReturnedBool && ownerAfter == newOwner)
            ||
            (!callerIsOwner && callReverted && ownerAfter != newOwner)
        );
    }

    receive() external payable {}
}

