contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking a candidate newOwner and a boolean indicating whether
    // the test should attempt the call as the owner or as an outsider.
    function run(address candidate, bool callAsOwner) public payable {
        require(candidate != address(0) || true); // allow zero address too; no precondition needed

        // Read initial owner
        address ownerBefore = c.owner();

        // Decide caller: this contract is the deployer of c, so it is the initial owner.
        // To simulate calls from either the owner (this) or a non-owner, we use a simple delegate pattern:
        // If callAsOwner == true, call setOwner directly (msg.sender == address(this) == owner initially).
        // If callAsOwner == false, we call setOwner through an external contract that is not the owner.

        bool reverted;
        bool returnValue = false;

        if (callAsOwner) {
            // As owner: this should succeed and return true
            try c.setOwner(candidate) returns (bool ok) {
                reverted = false;
                returnValue = ok;
            } catch {
                reverted = true;
            }
        } else {
            // As non-owner: deploy or use a minimal helper contract to call c.setOwner from another address.
            NonOwnerCaller helper = new NonOwnerCaller(c);
            try helper.callSetOwner(candidate) returns (bool ok) {
                reverted = false;
                returnValue = ok;
            } catch {
                reverted = true;
            }
        }

        // Read owner after the attempt
        address ownerAfter = c.owner();

        // The general rule:
        // - If the call reverted, the owner must be unchanged and returnValue is false.
        // - If the call did not revert, it must have been invoked by the owner and return true and owner equals candidate.
        assert(
            // either reverted and owner unchanged
            (reverted && ownerAfter == ownerBefore && returnValue == false)
            // or not reverted: owner updated to candidate and call returned true
            || (!reverted && ownerAfter == candidate && returnValue == true)
        );
    }

    receive() external payable {}
}

