    constructor(C _c) { c = _c; }

    // single public test function
    // candidate: the address to set as new owner
    // callAsOwner: if true, InvMutTest will call as the original deployer/owner (this contract);
    //              if false, the test will first change c.owner to another address so that this contract is not the owner,
    //              then attempt the call (so the call will be from a non-owner).
    function run(address candidate, bool callAsOwner) public payable {
        require(candidate != address(0) || true);

        // Read initial owner (should be address(this) because InvMutTest was deployer of c)
        address ownerBefore = c.owner();

        // If we want to simulate a non-owner calling, first change owner away from this contract.
        // Since c.setOwner can only be called by the current owner, ensure we perform that top-level.
        if (!callAsOwner) {
            // As current owner (this contract), set owner to candidate so that subsequent call from this contract is a non-owner call.
            // This is a state-changing top-level call on c.
            bool ok1 = c.setOwner(candidate);
            // read owner after first change
            address ownerMid = c.owner();
            // ensure the change succeeded as expected (otherwise the test cannot proceed meaningfully)
            require(ok1 && ownerMid == candidate);
        }

        // Now attempt the tested call: this contract calls setOwner(candidate).
        // This top-level state-changing call may succeed or revert. We capture revert with try/catch.
        bool reverted;
        bool returnValue = false;
        try c.setOwner(candidate) returns (bool rv) {
            reverted = false;
            returnValue = rv;
        } catch {
            reverted = true;
        }

        // Read owner after the attempt
        address ownerAfter = c.owner();

        // General rule assertion:
        // - If the call reverted, ownerAfter must equal ownerBefore if callAsOwner==true,
        //   or equal candidate if callAsOwner==false (because we changed it before attempting the call).
        // - If the call did not revert, it must have returned true and ownerAfter must equal candidate.
        assert(
            (reverted && ownerAfter == (callAsOwner ? ownerBefore : candidate))
            || (!reverted && returnValue == true && ownerAfter == candidate)
        );
    }

    receive() external payable {}
}

