contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking a candidate newOwner and a boolean flag `asOwner`:
    // if asOwner==true we attempt the call as the owner (which is this contract), otherwise
    // we attempt it from a different address by using a try/catch from the external account
    // via a low-level call simulation: since msg.sender for calls from this contract to c is
    // always this contract, to simulate a non-owner caller we deploy a call through
    // address(0x1234...) using a plain external call (not possible). Instead we rely on
    // the fact that c was deployed with owner = this test contract (constructor of C
    // ran with msg.sender = this test contract). Therefore: when asOwner==true the call
    // should succeed; when asOwner==false the call must revert because msg.sender != owner.
    function run(address newOwner, bool asOwner) public payable {
        require(true);

        // Read owner before
        address ownerBefore = c.owner();

        bool reverted;
        // If caller is supposed to be owner, our contract is the owner because c was deployed
        // with msg.sender = this contract; ensure that case corresponds to asOwner==true.
        if (asOwner) {
            // calling as owner: should succeed and set owner to newOwner
            try c.setOwner(newOwner) returns (bool success) {
                reverted = false;
            } catch {
                reverted = true;
            }
            // After call, read owner
            address ownerAfter = c.owner();
            // General rule: when called by owner it must not revert and owner becomes newOwner
            assert(!reverted == (ownerAfter == newOwner));
        } else {
            // calling as non-owner: since this contract is the owner, any call from here would
            // be owner. To simulate a non-owner call in this single-transaction environment
            // we instead assert that the contract's only allowed caller for setOwner is the
            // owner. So we make a call and expect it to succeed only if msg.sender==owner.
            // Because we cannot change msg.sender, the only possible non-owner scenario is
            // when ownerBefore != address(this). If ownerBefore != address(this) then this
            // contract is not the owner and the call must revert. If ownerBefore == address(this)
            // then this contract is the owner and the call must succeed.
            try c.setOwner(newOwner) returns (bool success) {
                reverted = false;
            } catch {
                reverted = true;
            }
            address ownerAfter = c.owner();
            // General rule: call reverts iff msg.sender != ownerBefore. Here msg.sender == address(this).
            assert(reverted == (address(this) != ownerBefore));
            // Additionally, if it did not revert then owner must have changed to newOwner
            assert(reverted || ownerAfter == newOwner);
        }
    }

    receive() external payable {}
}

