contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner) public payable {
        // record owner before the call
        address ownerBefore = c.owner();

        // attempt to call setOwner; capture whether it reverted
        bool reverted;
        bool ret;
        try c.setOwner(newOwner) returns (bool ok) {
            reverted = false;
            ret = ok;
        } catch {
            reverted = true;
            ret = false;
        }

        address ownerAfter = c.owner();

        // General invariant: ownerAfter is either ownerBefore or newOwner.
        // Additionally, if the call succeeded (didn't revert) then it must have returned true and ownerAfter == newOwner.
        assert((ownerAfter == ownerBefore || ownerAfter == newOwner) && (reverted || (ret == true && ownerAfter == newOwner)));
